import { Component, createRef } from 'preact'

import { deepEqual, sleep } from '../../utils'
import { Data, I18n } from '../../config'
import { SearchIndex, Store, FrequentlyUsed } from '../../helpers'
import Icons from '../../icons'

import { Emoji } from '../Emoji'
import { Navigation } from '../Navigation'
import { PureInlineComponent } from '../HOCs'

const Performance = {
  rowsPerRender: 10,
}

export default class Picker extends Component {
  constructor(props) {
    super()

    this.state = {
      pos: [-1, -1],
      skin: Store.get('skin') || props.skin,
      theme: this.initTheme(props.theme),
      visibleRows: { 0: true },
      /* pos is the current location the user has focused, while rememberedEmojiPosition
       is the emoji that would receive focus if the user tabbed to the emoji list from 
       anywhere else. When the user is in the grid, these are the same value, but when
        naving between tabs, pos would be [-1, -1] while rememberedEmojiPosition would 
        be the position which corresponds to the previously roved-to emoji
      */
      rememberedEmojiPosition: [0, 0],
    }
  }

  componentWillMount() {
    const { categories } = Data

    this.refs = {
      categories: new Map(),
      menu: createRef(),
      navigation: createRef(),
      scroll: createRef(),
      search: createRef(),
      searchInput: createRef(),
      skinToneButton: createRef(),
      skinToneRadio: createRef(),
      currentTargetEmoji: createRef(),
    }

    this.grid = []
    this.grid.setsize = 0

    const addRow = (rows, category) => {
      const row = []
      row.__categoryId = category.id
      row.__index = rows.length
      this.grid.push(row)

      const rowIndex = this.grid.length - 1
      const rowRef = rowIndex % Performance.rowsPerRender ? {} : createRef()
      rowRef.index = rowIndex
      rowRef.posinset = this.grid.setsize + 1
      rows.push(rowRef)

      return row
    }

    let numRows = 0
    for (let category of categories) {
      const rows = []
      let row = addRow(rows, category)

      for (let emoji of category.emojis) {
        if (row.length == this.props.perLine) {
          row = addRow(rows, category)
        }

        this.grid.setsize += 1
        row.push(emoji)
      }

      this.refs.categories.set(category.id, {
        root: createRef(),
        firstEmojiPosition: [numRows, 0],
        rows,
      })
      numRows += rows.length
    }
  }

  componentDidMount() {
    this.observeCategories()
    this.observeRows()

    this.shadowRoot = this.base.parentNode
    if (this.props.autoFocus && this.refs.searchInput.current) {
      this.refs.searchInput.current.focus()
    }
  }

  initTheme(theme) {
    if (theme != 'auto') return theme

    const darkMedia = matchMedia('(prefers-color-scheme: dark)')
    if (darkMedia.media.match(/^not/)) return 'light'

    darkMedia.addListener(() => {
      this.setState({ theme: darkMedia.matches ? 'dark' : 'light' })
    })

    return darkMedia.matches ? 'dark' : 'light'
  }

  handleBaseClick = (e) => {
    if (!this.state.showSkins) return
    if (!e.target.closest('.menu')) {
      e.preventDefault()
      e.stopImmediatePropagation()

      this.closeSkins()
    }
  }

  handleBaseKeydown = (e) => {
    if (!this.state.showSkins) return
    if (e.key == 'Escape') {
      e.preventDefault()
      e.stopImmediatePropagation()

      this.closeSkins()
      this.refs.skinToneButton.current.focus()
    }
  }

  getEmojiByPos([p1, p2]) {
    const grid = this.state.searchResults || this.grid
    const emoji = grid[p1] && grid[p1][p2]

    if (!emoji) return
    return SearchIndex.get(emoji)
  }

  observeCategories() {
    const navigation = this.refs.navigation.current
    if (!navigation) return

    const visibleCategories = new Map()
    const setFocusedCategory = (categoryId, categoryIndex) => {
      if (categoryId != navigation.state.categoryId) {
        navigation.setState({ categoryId, categoryIndex })
      }
    }

    const observerOptions = {
      root: this.refs.scroll.current,
      threshold: [0.0, 1.0],
    }

    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        const id = entry.target.dataset.id
        visibleCategories.set(id, entry.intersectionRatio)
      }

      const ratios = [...visibleCategories]

      const lastCategory = ratios[ratios.length - 1]
      if (lastCategory[1] == 1) {
        return setFocusedCategory(lastCategory[0], ratios.length - 1)
      }

      for (let i = 0; i < ratios.length; i += 1) {
        const [id, ratio] = ratios[i]
        if (ratio) {
          setFocusedCategory(id, i)
          break
        }
      }
    }, observerOptions)

    for (const { root } of this.refs.categories.values()) {
      observer.observe(root.current)
    }
  }

  observeRows() {
    const visibleRows = { ...this.state.visibleRows }

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const index = parseInt(entry.target.dataset.index)

          if (entry.isIntersecting) {
            visibleRows[index] = true
          } else {
            delete visibleRows[index]
          }
        }

        this.setState({ visibleRows })
      },
      {
        root: this.refs.scroll.current,
        rootMargin: `${
          this.props.emojiButtonSize * (Performance.rowsPerRender + 5)
        }px 0px ${this.props.emojiButtonSize * Performance.rowsPerRender}px`,
      },
    )

    for (const { rows } of this.refs.categories.values()) {
      for (const row of rows) {
        if (row.current) {
          observer.observe(row.current)
        }
      }
    }
  }

  preventDefault(e) {
    e.preventDefault()
  }

  handleSearchClick = () => {
    const emoji = this.getEmojiByPos(this.state.pos)
    if (!emoji) return

    this.setState({ pos: [-1, -1], rememberedEmojiPosition: [0, 0] })
  }

  handleSearchInput = async () => {
    const input = this.refs.searchInput.current
    if (!input) return

    const { value } = input
    const searchResults = await SearchIndex.search(value)
    const afterRender = () => {
      if (!this.refs.scroll.current) return
      this.refs.scroll.current.scrollTop = 0
    }

    if (!searchResults) {
      this.setState(
        { searchResults, pos: [-1, -1], rememberedEmojiPosition: [0, 0] },
        afterRender,
      )
      return
    }

    const pos = input.selectionStart == input.value.length ? [0, 0] : [-1, -1]
    const grid = []
    grid.setsize = searchResults.length
    let row = null

    for (let emoji of searchResults) {
      if (!grid.length || row.length == this.props.perLine) {
        row = []
        row.__categoryId = 'search'
        row.__index = grid.length
        grid.push(row)
      }

      row.push(emoji)
    }

    this.ignoreMouse()
    this.setState(
      { searchResults: grid, pos, rememberedEmojiPosition: [0, 0] },
      afterRender,
    )
  }

  handleKeyDown = (e) => {
    e.stopImmediatePropagation()

    switch (e.key) {
      case 'Escape':
        if (this.props.onEscapeKeydown) {
          this.props.onEscapeKeydown()
        }
        break
      default:
        break
    }
  }

  handleSearchKeyDown = (e) => {
    e.stopImmediatePropagation()

    switch (e.key) {
      case 'Enter':
        const value = this.refs.searchInput.current?.value
        e.preventDefault()
        if (value) {
          // When someone hits enter with text in the search bar
          // We want to add the first emoji that shows up
          this.handleEmojiClick({ pos: [0, 0] })
        }
        break
      default:
        break
    }
  }

  handleGridKeyDown = (e) => {
    const input = e.currentTarget
    e.stopImmediatePropagation()

    switch (e.key) {
      case 'ArrowLeft':
        this.navigate({ e, input, left: true })
        break

      case 'ArrowRight':
        this.navigate({ e, input, right: true })
        break

      case 'ArrowUp':
        this.navigate({ e, input, up: true })
        break

      case 'ArrowDown':
        this.navigate({ e, input, down: true })
        break

      case 'Enter':
        e.preventDefault()
        this.handleEmojiClick({ pos: this.state.pos })
        break

      case 'Escape':
        e.preventDefault()
        if (this.state.searchResults) {
          this.clearSearch()
        } else if (this.props.onEscapeKeydown) {
          this.props.onEscapeKeydown()
        } else {
          this.unfocusSearch()
        }
        break

      default:
        break
    }
  }

  clearSearch = () => {
    const input = this.refs.searchInput.current
    if (!input) return

    input.value = ''
    input.focus()

    this.handleSearchInput()
  }

  unfocusSearch() {
    const input = this.refs.searchInput.current
    if (!input) return

    input.blur()
  }

  navigate({ e, input, left, right, up, down }) {
    const grid = this.state.searchResults || this.grid
    if (!grid.length) return

    let [p1, p2] = this.state.pos

    const pos = (() => {
      if (p1 == 0) {
        if (p2 == 0 && !e.repeat && (left || up)) {
          return null
        }
      }

      if (p1 == -1) {
        if (
          !e.repeat &&
          (right || down) &&
          input.selectionStart == input.value.length
        ) {
          return [0, 0]
        }

        return null
      }

      if (left || right) {
        let row = grid[p1]
        const increment = left ? -1 : 1

        p2 += increment
        if (!row[p2]) {
          p1 += increment
          row = grid[p1]

          if (!row) {
            p1 = left ? 0 : grid.length - 1
            p2 = left ? 0 : grid[p1].length - 1

            return [p1, p2]
          }

          p2 = left ? row.length - 1 : 0
        }

        return [p1, p2]
      }

      if (up || down) {
        p1 += up ? -1 : 1
        const row = grid[p1]

        if (!row) {
          p1 = up ? 0 : grid.length - 1
          p2 = up ? 0 : grid[p1].length - 1

          return [p1, p2]
        }

        if (!row[p2]) {
          p2 = row.length - 1
        }

        return [p1, p2]
      }
    })()

    if (pos) {
      e.preventDefault()
    } else {
      if (this.state.pos[0] > -1) {
        this.setState({ pos: [-1, -1], rememberedEmojiPosition: [0, 0] })
      }

      return
    }

    this.setState({ pos, rememberedEmojiPosition: pos, keyboard: true }, () => {
      this.scrollTo({ row: pos[0] })
      this.refs.currentTargetEmoji.current?.focus()
    })
  }

  scrollTo({ categoryId, row }) {
    const grid = this.state.searchResults || this.grid
    if (!grid.length) return

    const scroll = this.refs.scroll.current
    const scrollRect = scroll.getBoundingClientRect()

    let scrollTop = 0

    if (row >= 0) {
      categoryId = grid[row].__categoryId
    }

    if (categoryId) {
      const ref =
        this.refs[categoryId] || this.refs.categories.get(categoryId).root
      const categoryRect = ref.current.getBoundingClientRect()

      scrollTop = categoryRect.top - (scrollRect.top - scroll.scrollTop) + 1
    }

    if (row >= 0) {
      if (!row) {
        scrollTop = 0
      } else {
        const rowIndex = grid[row].__index
        const rowTop = scrollTop + rowIndex * this.props.emojiButtonSize
        const rowBot =
          rowTop +
          this.props.emojiButtonSize +
          this.props.emojiButtonSize * 0.88

        if (rowTop < scroll.scrollTop) {
          scrollTop = rowTop
        } else if (rowBot > scroll.scrollTop + scrollRect.height) {
          scrollTop = rowBot - scrollRect.height
        } else {
          return
        }
      }
    }

    this.ignoreMouse()
    scroll.scrollTop = scrollTop
  }

  ignoreMouse() {
    this.mouseIsIgnored = true
    clearTimeout(this.ignoreMouseTimer)
    this.ignoreMouseTimer = setTimeout(() => {
      delete this.mouseIsIgnored
    }, 100)
  }

  handleCategorySelect = ({ category, i }) => {
    this.scrollTo(i == 0 ? { row: -1 } : { categoryId: category.id })
    const firstEmojiPosition = this.refs.categories.get(
      category.id,
    ).firstEmojiPosition
    this.setState({
      rememberedEmojiPosition: firstEmojiPosition,
    })
  }

  handleEmojiOver(pos) {
    if (this.mouseIsIgnored || this.state.showSkins) return
    this.setState({
      pos: pos || [-1, -1],
      keyboard: false,
      rememberedEmojiPosition: pos || [0, 0],
    })
  }

  handleEmojiClick({ emoji, pos }) {
    if (!this.props.onEmojiSelect) return

    if (!emoji && pos) {
      emoji = this.getEmojiByPos(pos)
    }

    if (emoji) {
      const skin = emoji.skins[this.state.skin - 1] || emoji.skins[0]
      const emojiData = {
        id: emoji.id,
        unified: skin.unified,
        keywords: emoji?.keywords || [],
        shortcodes: skin.shortcodes || emoji.shortcodes,
      }

      if (skin.src) {
        emojiData.src = skin.src
      }

      if (emoji.aliases && emoji.aliases.length) {
        emojiData.aliases = emoji.aliases
      }

      if (this.props.maxFrequentRows) {
        FrequentlyUsed.add(emojiData, this.props)
      }

      this.props.onEmojiSelect(emojiData)
    }
  }

  openSkins = (e) => {
    const { currentTarget } = e
    const rect = currentTarget.getBoundingClientRect()

    this.setState({ showSkins: rect }, async () => {
      // Firefox requires 2 frames for the transition to consistenly work
      await sleep(2)

      const menu = this.refs.menu.current
      if (!menu) return

      menu.classList.remove('hidden')
      this.refs.skinToneRadio.current.focus()

      this.base.addEventListener('click', this.handleBaseClick, true)
      this.base.addEventListener('keydown', this.handleBaseKeydown, true)
    })
  }

  closeSkins() {
    if (!this.state.showSkins) return
    this.setState({ showSkins: null, tempSkin: null })

    this.base.removeEventListener('click', this.handleBaseClick)
    this.base.removeEventListener('keydown', this.handleBaseKeydown)
  }

  handleSkinMouseOver(tempSkin) {
    this.setState({ tempSkin })
  }

  handleSkinClick(skin) {
    this.ignoreMouse()
    this.closeSkins()

    this.setState({ skin, tempSkin: null })
    Store.set('skin', skin)
  }

  renderNav() {
    return (
      <Navigation
        ref={this.refs.navigation}
        theme={this.state.theme}
        showTabBar={!!this.state.searchResults}
        position={this.props.navPosition}
        onCategoryChange={this.handleCategorySelect}
      />
    )
  }

  renderPreview() {
    const emoji = this.getEmojiByPos(this.state.pos)
    const noSearchResults =
      this.state.searchResults && !this.state.searchResults.length
    const emojiSize = 22
    const emojiButtonSize = emojiSize + 8
    return (
      <div
        id="preview"
        class="flex flex-middle"
        data-position={this.props.previewPosition}
      >
        <div class="flex flex-middle flex-grow" style={{ padding: '4px 0px' }}>
          <div
            class="flex flex-auto flex-middle flex-center"
            style={{
              height: emojiButtonSize,
              width: emojiButtonSize,
              fontSize: emojiButtonSize,
            }}
          >
            <Emoji
              emoji={emoji}
              id={
                noSearchResults
                  ? this.props.noResultsEmoji || 'cry'
                  : this.props.previewEmoji ||
                    (this.props.previewPosition == 'top'
                      ? 'point_down'
                      : 'point_up')
              }
              set={this.props.set}
              size={emojiSize}
              skin={this.state.tempSkin || this.state.skin}
              spritesheet={true}
            />
          </div>
          {emoji ? (
            <div class="ellipsis color-c">{emoji.skins[0].shortcodes}</div>
          ) : noSearchResults ? (
            <div class="ellipsis color-c" aria-live="polite">
              {I18n.search_no_results}
            </div>
          ) : (
            <div class="color-c">{I18n.pick}</div>
          )}
        </div>

        {this.renderSkinToneButton()}
      </div>
    )
  }

  renderEmojiButton(emoji, { pos, posinset, grid }) {
    const size = this.props.emojiButtonSize
    const skin = this.state.tempSkin || this.state.skin
    const selected = deepEqual(this.state.pos, pos)
    const key = pos.concat(emoji.id).join('')
    const isCurrentEmojiTarget =
      pos[0] === this.state.rememberedEmojiPosition[0] &&
      pos[1] === this.state.rememberedEmojiPosition[1]

    // This is used for a roving tab index in the grid
    const tabIndex = isCurrentEmojiTarget ? 0 : -1

    return (
      <PureInlineComponent
        key={key}
        {...{ selected, skin, size, isCurrentEmojiTarget }}
      >
        <button
          aria-label={emoji.id}
          aria-selected={selected || undefined}
          aria-posinset={posinset}
          aria-setsize={grid.setsize}
          data-keyboard={this.state.keyboard}
          title={this.props.previewPosition == 'none' ? emoji.id : undefined}
          type="button"
          class="flex flex-center flex-middle"
          tabIndex={tabIndex}
          ref={isCurrentEmojiTarget ? this.refs.currentTargetEmoji : undefined}
          onFocus={() => {
            this.setState({ pos: pos })
          }}
          onClick={() => this.handleEmojiClick({ emoji })}
          onMouseEnter={() => this.handleEmojiOver(pos)}
          onMouseLeave={() => this.handleEmojiOver()}
          style={{
            width: this.props.emojiButtonSize,
            height: this.props.emojiButtonSize,
            fontSize: this.props.emojiSize,
            lineHeight: 0,
            fontFamily:
              'EmojiMart, Segoe UI Emoji, Segoe UI Symbol, Segoe UI, Apple Color Emoji, Twemoji Mozilla, Noto Color Emoji, Android Emoji',
          }}
        >
          <div
            aria-hidden="true"
            class="background"
            style={{
              borderRadius: this.props.emojiButtonRadius,
              backgroundColor: this.props.emojiButtonColors
                ? this.props.emojiButtonColors[
                    (posinset - 1) % this.props.emojiButtonColors.length
                  ]
                : undefined,
            }}
          ></div>
          <Emoji
            emoji={emoji}
            set={this.props.set}
            size={this.props.emojiSize}
            skin={skin}
            spritesheet={true}
          />
        </button>
      </PureInlineComponent>
    )
  }

  renderSearch() {
    return (
      <div>
        <div class="spacer"></div>
        <div class="flex flex-middle">
          <div class="search relative flex-grow">
            <input
              type="search"
              autoFocus={this.props.autoFocus}
              ref={this.refs.searchInput}
              placeholder={I18n.search}
              onClick={this.handleSearchClick}
              onInput={this.handleSearchInput}
              onKeyDown={this.handleSearchKeyDown}
              aria-description={I18n.search_will_update}
              aria-label={I18n.search_for_emojis}
            ></input>
            <span class="icon loupe flex" aria-hidden={true}>
              {Icons.search.loupe}
            </span>
            {this.state.searchResults && (
              <button
                title="Clear"
                aria-label="Clear"
                type="button"
                class="icon delete flex"
                onClick={this.clearSearch}
                onMouseDown={this.preventDefault}
              >
                {Icons.search.delete}
              </button>
            )}
          </div>

          {this.props.previewPosition == 'none' && this.renderSkinToneButton()}
        </div>
      </div>
    )
  }

  renderSearchResults() {
    const { searchResults } = this.state
    if (!searchResults) return null

    return (
      <div class="category" ref={this.refs.search}>
        <div class="sticky padding-small">{I18n.categories.search}</div>
        <div onKeyDown={this.handleGridKeyDown}>
          {searchResults.map((row, i) => {
            return (
              <div class="flex">
                {row.map((emoji, ii) => {
                  return this.renderEmojiButton(emoji, {
                    pos: [i, ii],
                    posinset: i * this.props.perLine + ii + 1,
                    grid: searchResults,
                  })
                })}
              </div>
            )
          })}
        </div>
      </div>
    )
  }

  renderCategories() {
    const { categories } = Data
    const hidden = !!this.state.searchResults

    return (
      <div
        style={{
          visibility: hidden ? 'hidden' : undefined,
          display: hidden ? 'none' : undefined,
        }}
        onKeyDown={this.handleGridKeyDown}
      >
        {categories.map((category) => {
          const { root, rows } = this.refs.categories.get(category.id)

          return (
            <div
              data-id={category.target ? category.target.id : category.id}
              class="category"
              ref={root}
              role="tabpanel"
            >
              <div class="sticky padding-small">
                <h2> {category.name || I18n.categories[category.id]} </h2>
              </div>
              <div
                class="relative"
                style={{
                  height: rows.length * this.props.emojiButtonSize,
                }}
                role="list"
                aria-label={category.name || I18n.categories[category.id]}
              >
                {rows.map((row, i) => {
                  const targetRow =
                    row.index - (row.index % Performance.rowsPerRender)
                  const visible = this.state.visibleRows[targetRow]
                  const ref = 'current' in row ? row : undefined

                  if (!visible && !ref) {
                    return null
                  }

                  const start = i * this.props.perLine
                  const end = start + this.props.perLine
                  const emojiIds = category.emojis.slice(start, end)

                  return (
                    <div
                      key={row.index}
                      data-index={row.index}
                      ref={ref}
                      class="flex row"
                      style={{ top: i * this.props.emojiButtonSize }}
                    >
                      {visible &&
                        emojiIds.map((emojiId, ii) => {
                          const emoji = SearchIndex.get(emojiId)

                          return this.renderEmojiButton(emoji, {
                            pos: [row.index, ii],
                            posinset: row.posinset + ii,
                            grid: this.grid,
                          })
                        })}
                    </div>
                  )
                })}
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  renderSkinToneButton() {
    return (
      <div
        class="flex flex-auto flex-center flex-middle"
        style={{
          position: 'relative',
          width: this.props.emojiButtonSize,
          height: this.props.emojiButtonSize,
        }}
      >
        <button
          type="button"
          ref={this.refs.skinToneButton}
          class="skin-tone-button flex flex-auto flex-center flex-middle"
          aria-selected={this.state.showSkins ? '' : undefined}
          aria-label={`${I18n.skins.choose}, ${I18n.skins[this.state.skin]}`}
          title={I18n.skins.choose}
          onClick={this.openSkins}
          style={{
            width: this.props.emojiSize,
            height: this.props.emojiSize,
          }}
          aria-controls={'skin-tone-selector'}
          aria-haspopup={true}
          aria-expanded={this.state.showSkins}
        >
          <span class={`skin-tone skin-tone-${this.state.skin}`}></span>
        </button>
      </div>
    )
  }

  renderSkins() {
    const skinToneButton = this.refs.skinToneButton.current
    const skinToneButtonRect = skinToneButton.getBoundingClientRect()
    const baseRect = this.base.getBoundingClientRect()

    const position = {
      right: baseRect.right - skinToneButtonRect.right - 3,
    }

    if (this.props.previewPosition == 'bottom') {
      position.bottom = baseRect.bottom - skinToneButtonRect.top + 4
    } else {
      position.top = skinToneButtonRect.bottom - baseRect.top + 3
      position.bottom = 'auto'
    }

    return (
      <div
        ref={this.refs.menu}
        role="radiogroup"
        id={'skin-tone-selector'}
        aria-label={I18n.skins.choose}
        class="menu hidden"
        data-position={position.top ? 'top' : 'bottom'}
        style={position}
      >
        {[...Array(6).keys()].map((i) => {
          const skin = i + 1
          const checked = this.state.skin == skin

          return (
            <div>
              <input
                type="radio"
                name="skin-tone"
                value={skin}
                aria-label={I18n.skins[skin]}
                ref={checked ? this.refs.skinToneRadio : null}
                defaultChecked={checked}
                onChange={() => this.handleSkinMouseOver(skin)}
                onKeyDown={(e) => {
                  if (
                    e.code == 'Enter' ||
                    e.code == 'Space' ||
                    e.code == 'Tab'
                  ) {
                    e.preventDefault()
                    this.handleSkinClick(skin)
                    this.refs.skinToneButton.current.focus()
                  }
                }}
              ></input>

              <button
                aria-hidden="true"
                tabindex="-1"
                onClick={() => this.handleSkinClick(skin)}
                onMouseEnter={() => this.handleSkinMouseOver(skin)}
                onMouseLeave={() => this.handleSkinMouseOver()}
                class="option flex flex-grow flex-middle"
              >
                <span class={`skin-tone skin-tone-${skin}`}></span>
                <span class="margin-small-lr">{I18n.skins[skin]}</span>
              </button>
            </div>
          )
        })}
      </div>
    )
  }

  render() {
    return (
      <section
        id="root"
        class="flex flex-column"
        style={{
          width: this.props.perLine * this.props.emojiButtonSize + (12 + 16),
        }}
        data-emoji-set={this.props.set}
        data-theme={this.state.theme}
        data-menu={this.state.showSkins ? '' : undefined}
        onKeyDown={this.handleKeyDown}
      >
        {this.props.previewPosition == 'top' && this.renderPreview()}
        {this.props.navPosition == 'top' && this.renderNav()}
        {this.props.stickySearch && (
          <div class="padding-lr">{this.renderSearch()}</div>
        )}

        <div ref={this.refs.scroll} class="scroll flex-grow padding-lr">
          <div
            style={{
              width: this.props.perLine * this.props.emojiButtonSize,
            }}
          >
            {!this.props.stickySearch && this.renderSearch()}
            {this.renderSearchResults()}
            {this.renderCategories()}

            <div class="spacer"></div>
          </div>
        </div>

        {this.props.navPosition == 'bottom' && this.renderNav()}
        {this.props.previewPosition == 'bottom' && this.renderPreview()}
        {this.state.showSkins && this.renderSkins()}
      </section>
    )
  }
}
